@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {}

class Patient {
  + consentSigned : boolean
}

class Doctor {
  + approveDiagnosis(diagnosis: Diagnosis)
  + downgradeTreatment(treatment: Treatment)
}

class Nurse {}

class Illness {
  + priorityScore : PriorityScore
}

class Diagnosis {
  + Id : string
}

class Treatment {
  + stage : int
}

class TreatmentForm {
  + signedDate : date
}

HospitalHouseMD "1" -- "*" Illness
HospitalHouseMD "1" -- "*" Diagnosis
HospitalHouseMD "1" -- "*" Treatment

Patient "1" -- "1..*" Doctor : is assigned to
Patient "1" -- "0..*" Diagnosis : has
Patient "1" -- "0..*" Treatment : undergoes
Patient "1" -- "0..*" TreatmentForm : signs

Doctor "1" -- "0..*" Diagnosis : makes
Doctor "1" -- "0..*" Treatment : manages
Doctor "1" -- "0..*" Nurse : works with

Nurse "1" -- "0..*" Treatment : follows up

Illness "1" -- "0..*" Diagnosis : causes
Illness "1" -- "0..*" Treatment : has possible
Diagnosis "1" -- "0..*" Treatment : has

@enduml

